// CatalogServiceHandler is an implementation of the catalog.v1.CatalogService service.
type CatalogServiceHandler interface {
	// Reads
	GetVideo(context.Context, *connect.Request[v1.GetVideoRequest]) (*connect.Response[v1.GetVideoResponse], error)
	// Hydrates ids returned by the recommendation service. Order of the request
	// is preserved in the response so ranking survives the round trip.
	BatchGetVideos(context.Context, *connect.Request[v1.BatchGetVideosRequest]) (*connect.Response[v1.BatchGetVideosResponse], error)
	SearchVideos(context.Context, *connect.Request[v1.SearchVideosRequest]) (*connect.Response[v1.SearchVideosResponse], error)
	// Type-ahead over the local library only. Suggesting terms the library
	// cannot answer would lead every one of them to an empty result page.
	Suggest(context.Context, *connect.Request[v1.SuggestRequest]) (*connect.Response[v1.SuggestResponse], error)
	ListChannelVideos(context.Context, *connect.Request[v1.ListChannelVideosRequest]) (*connect.Response[v1.ListChannelVideosResponse], error)
	GetChannel(context.Context, *connect.Request[v1.GetChannelRequest]) (*connect.Response[v1.GetChannelResponse], error)
	// Topics actually present in the library, for the home chip bar and sidebar.
	ListTopics(context.Context, *connect.Request[v1.ListTopicsRequest]) (*connect.Response[v1.ListTopicsResponse], error)
	// Lightweight ranking features, pulled by the recommendation service so it
	// can rank without ever reading this service's database.
	ListVideoFeatures(context.Context, *connect.Request[v1.ListVideoFeaturesRequest]) (*connect.Response[v1.ListVideoFeaturesResponse], error)
	// Writes, called by the ingest worker as a video moves through the pipeline.
	UpsertChannel(context.Context, *connect.Request[v1.UpsertChannelRequest]) (*connect.Response[v1.UpsertChannelResponse], error)
	UpsertVideo(context.Context, *connect.Request[v1.UpsertVideoRequest]) (*connect.Response[v1.UpsertVideoResponse], error)
	SetMediaState(context.Context, *connect.Request[v1.SetMediaStateRequest]) (*connect.Response[v1.SetMediaStateResponse], error)
	// Records whether a video is a Short. Ingest asks YouTube; catalog stores the
	// answer, because "is this a Short" is a property of the video the library
	// holds rather than of the fetch that found it.
	SetShort(context.Context, *connect.Request[v1.SetShortRequest]) (*connect.Response[v1.SetShortResponse], error)
	// The videos nobody has asked about yet, newest first.
	ListUncheckedShorts(context.Context, *connect.Request[v1.ListUncheckedShortsRequest]) (*connect.Response[v1.ListUncheckedShortsResponse], error)
	// Resolves an external source URL to an existing library entry, so the same
	// video is never ingested twice.
	FindBySourceURL(context.Context, *connect.Request[v1.FindBySourceURLRequest]) (*connect.Response[v1.FindBySourceURLResponse], error)
	// Comments
	ListComments(context.Context, *connect.Request[v1.ListCommentsRequest]) (*connect.Response[v1.ListCommentsResponse], error)
	CreateComment(context.Context, *connect.Request[v1.CreateCommentRequest]) (*connect.Response[v1.CreateCommentResponse], error)
	// Batch import of YouTube comments. Idempotent: comments whose id already
	// exists are skipped with ON CONFLICT DO NOTHING.
	ImportComments(context.Context, *connect.Request[v1.ImportCommentsRequest]) (*connect.Response[v1.ImportCommentsResponse], error)
	// Interaction state. Lives here rather than in a separate service because
	// almost every video read needs it; splitting it out would turn one call
	// into an N+1 fan-out on the home grid.
	RecordWatchProgress(context.Context, *connect.Request[v1.RecordWatchProgressRequest]) (*connect.Response[v1.RecordWatchProgressResponse], error)
	SetReaction(context.Context, *connect.Request[v1.SetReactionRequest]) (*connect.Response[v1.SetReactionResponse], error)
	SetSubscription(context.Context, *connect.Request[v1.SetSubscriptionRequest]) (*connect.Response[v1.SetSubscriptionResponse], error)
	ListSubscriptions(context.Context, *connect.Request[v1.ListSubscriptionsRequest]) (*connect.Response[v1.ListSubscriptionsResponse], error)
	ListHistory(context.Context, *connect.Request[v1.ListHistoryRequest]) (*connect.Response[v1.ListHistoryResponse], error)
	// Watch Later. The table and the read have existed since 0001_init — every
	// video already reports user_state.in_watch_later — but nothing could ever
	// write it, so it answered false for everybody, forever.
	SetWatchLater(context.Context, *connect.Request[v1.SetWatchLaterRequest]) (*connect.Response[v1.SetWatchLaterResponse], error)
	ListWatchLater(context.Context, *connect.Request[v1.ListWatchLaterRequest]) (*connect.Response[v1.ListWatchLaterResponse], error)
	// Playlists, per member. Watch Later is deliberately not one of these: it has
	// no name, cannot be created and cannot be deleted, so as a row here it would
	// be a playlist that is not one.
	ListPlaylists(context.Context, *connect.Request[v1.ListPlaylistsRequest]) (*connect.Response[v1.ListPlaylistsResponse], error)
	GetPlaylist(context.Context, *connect.Request[v1.GetPlaylistRequest]) (*connect.Response[v1.GetPlaylistResponse], error)
	CreatePlaylist(context.Context, *connect.Request[v1.CreatePlaylistRequest]) (*connect.Response[v1.CreatePlaylistResponse], error)
	UpdatePlaylist(context.Context, *connect.Request[v1.UpdatePlaylistRequest]) (*connect.Response[v1.UpdatePlaylistResponse], error)
	DeletePlaylist(context.Context, *connect.Request[v1.DeletePlaylistRequest]) (*connect.Response[v1.DeletePlaylistResponse], error)
	// One toggle rather than an add/remove pair: the caller always knows which
	// way the menu entry is facing, and two RPCs would be two places to get the
	// position rules wrong.
	SetPlaylistItem(context.Context, *connect.Request[v1.SetPlaylistItemRequest]) (*connect.Response[v1.SetPlaylistItemResponse], error)
	// Storage. Backs the Storage page and the eviction banner.
	GetStorageUsage(context.Context, *connect.Request[v1.GetStorageUsageRequest]) (*connect.Response[v1.GetStorageUsageResponse], error)
	SetPinned(context.Context, *connect.Request[v1.SetPinnedRequest]) (*connect.Response[v1.SetPinnedResponse], error)
	// Videos the viewer has chosen to keep. "Saved" is the browsing view; pinning
	// is also the mechanism that protects a video from eviction.
	ListPinnedVideos(context.Context, *connect.Request[v1.ListPinnedVideosRequest]) (*connect.Response[v1.ListPinnedVideosResponse], error)
}

